INSERT INTO buffer_mensajes (lead_id, msg_id, texto)
VALUES ($1, $2, $3)
ON CONFLICT (msg_id) DO NOTHING;

SELECT
  (SELECT COUNT(*) FROM buffer_mensajes
     WHERE lead_id = $1 AND consumido_en IS NULL
       AND recibido_en > (SELECT recibido_en FROM buffer_mensajes WHERE msg_id = $2)
  ) AS mas_nuevos,
  (SELECT string_agg(texto, chr(10) ORDER BY recibido_en)
     FROM buffer_mensajes WHERE lead_id = $1 AND consumido_en IS NULL
  ) AS chats,
  (SELECT COUNT(*) FROM buffer_mensajes
     WHERE lead_id = $1 AND consumido_en IS NULL) AS cuantos;

UPDATE buffer_mensajes SET consumido_en = now()
 WHERE lead_id = $1 AND consumido_en IS NULL
 RETURNING msg_id;

